import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.Cv-B11KK.js";const u=JSON.parse('{"title":"Project-aware builds","description":"","frontmatter":{},"headers":[],"relativePath":"project-builds.md","filePath":"project-builds.md","lastUpdated":1790322248000}'),n={name:"project-builds.md"};function o(r,e,l,d,c,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="project-aware-builds" tabindex="-1">Project-aware builds <a class="header-anchor" href="#project-aware-builds" aria-label="Permalink to &quot;Project-aware builds&quot;">​</a></h1><p>⌘K saves the active document, then modified <code>.tex</code>, <code>.bib</code>, <code>.sty</code>, and <code>.cls</code> files open under the project directory (and the explicit root), before building. The project directory is the directory containing <code>.bbtex</code>, or the final root file&#39;s directory when no configuration exists. Untitled files are not saved. Save edits to <code>.bbtex</code> itself before compiling.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="document-comments-the-texshop-convention" tabindex="-1">Document comments: the TeXShop convention <a class="header-anchor" href="#document-comments-the-texshop-convention" aria-label="Permalink to &quot;Document comments: the TeXShop convention&quot;">​</a></h3><p><code>%!TEX root = ...</code> and <code>%!TEX program = ...</code> are editor instructions embedded in ordinary LaTeX comments. The convention comes from TeXShop and is also used by LaTeXTools. TeX itself ignores these lines; the editor/build wrapper reads them. This is an editor convention, not an official LaTeX standard. AUCTeX&#39;s <code>TeX-master</code> and <code>TeX-engine</code> local variables are a different format and are not currently read by bbtex.</p><p>References: <a href="https://pages.uoregon.edu/koch/texshop/" target="_blank" rel="noreferrer">TeXShop</a> and <a href="https://latextools.readthedocs.io/en/latest/features/" target="_blank" rel="noreferrer">LaTeXTools magic-comment support</a>. bbtex reads comments from the first 50 lines. Both <code>%!TEX</code> and <code>% !TEX</code> are accepted, case-insensitively, as are <code>program</code> and TeXShop&#39;s <code>TS-program</code> alias. The supported engine values are <code>pdflatex</code>, <code>xelatex</code>, <code>lualatex</code>, and <code>tectonic</code>. TeXShop&#39;s built-in engine names are accepted too: <code>pdflatexmk</code>, <code>latexmk</code> and <code>LaTeX</code> mean pdflatex, <code>xelatexmk</code> means xelatex, and <code>lualatexmk</code> means lualatex. Other TeXShop engine scripts are not supported. No other comments are read: <code>% !TEX encoding</code> is parsed but not used, and TeXShop&#39;s <code>spellcheck</code>, <code>parameter</code> and <code>% !BIB TS-program</code>, and LaTeXTools&#39; <code>options</code>, <code>output_directory</code> and <code>jobname</code>, are ignored. Put options and the output directory in a <code>.bbtex</code> file instead (below). The <a href="./editor-comparison#magic-comments">comparison</a> lists them side by side. A UTF-8 byte-order mark before the first directive is ignored. The setup helper normalizes these variants when replacing settings, avoiding duplicate directives.</p><p>For guided setup, press ⇧⌘K and choose <strong>Configure Document…</strong>. Choose whether this file is the main document or select a main <code>.tex</code> file anywhere on disk. The file chooser starts in the current source document&#39;s directory. The engine picker explains the usual use cases; included files can inherit the main document&#39;s engine. The helper saves your current edits, replaces the root/program comments, and leaves the result unsaved for review. Press ⌘K to save and compile. Project profile engines still take precedence.</p><p>For example, <code>tables/table1.tex</code> included by <code>main.tex</code> can start with:</p><div class="language-latex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">latex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">%!TEX root = ../main.tex</span></span></code></pre></div><p>The helper generates this relative path, including for main files outside the current folder. bbtex does not guess a parent from <code>\\\\input</code>: the same table can be included by several documents. Choose the one you want to build. A shared <code>.bbtex</code> root setting also works for files beneath its directory.</p><h3 id="shared-project-settings" tabindex="-1">Shared project settings <a class="header-anchor" href="#shared-project-settings" aria-label="Permalink to &quot;Shared project settings&quot;">​</a></h3><p>Put a file named <code>.bbtex</code> at the top of the project. This is bbtex&#39;s own format, separate from TeXShop&#39;s comments. The format is plain <code>key = value</code> lines, with optional profile sections. <code>#</code> and <code>;</code> start comment lines. Path values are written literally, without surrounding quotes.</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = main.tex</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = pdflatex</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">output_directory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[profile Draft]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = pdflatex</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = -halt-on-error</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[profile XeLaTeX]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = xelatex</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[profile Tectonic]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">engine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = tectonic</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">options</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">reruns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span></code></pre></div><p><code>root</code> is relative to the configuration file. <code>output_directory</code> is relative to the final root <code>.tex</code> file; omit it to write beside the root file. All profiles share this output directory so results, cleanup, and forward search agree. For nested <code>\\include{chapters/...}</code> files, bbtex recovers missing auxiliary subdirectories inside that output directory and retries latexmk. Recovery is limited to 16 attempts and does not follow symlink parents or paths escaping the output tree. Other write errors remain build failures.</p><p>Optionally add <code>default_profile = Draft</code> above the profile sections to use that profile for ordinary ⌘K builds. Profile names are case-sensitive. Profiles can override <code>engine</code> and append <code>options</code>; <code>root</code> and <code>output_directory</code> are global.</p><p>⇧⌘K lists the four engines and each named project profile. A selection applies only to that build. Neither the source nor configuration is rewritten.</p><p>Engine precedence: explicit engine choice, selected/default profile engine, first <code>%!TEX program</code> in the source-to-root chain, project engine, pdfLaTeX. A source <code>%!TEX root</code> takes precedence over the project&#39;s <code>root</code> setting. Root directives can chain through files; a self-root is allowed, cycles and missing or non-TeX roots produce an error. Symlinks resolve to the same root.</p><p>Options are passed as separate arguments, never evaluated by a shell. Use <code>--option=value</code> for options taking values; quote values containing spaces inside <code>options</code>. Engine, output-path, cleanup, and watch-mode flags are managed by bbtex and cannot be supplied as extra options. Unknown settings and malformed quotes fail before compilation.</p><h2 id="running-and-cancelling" tabindex="-1">Running and cancelling <a class="header-anchor" href="#running-and-cancelling" aria-label="Permalink to &quot;Running and cancelling&quot;">​</a></h2><p>Build notifications show the root and engine, then elapsed time and diagnostics. Only one build or cleanup may run for a given root. A second request reports that the project is busy; it does not start another compiler. Different roots can build independently.</p><p>Choose <strong>LaTeX — Cancel Build</strong> from any file resolving to the same root. It requests cancellation from the running build, which stops the compiler&#39;s process group, including TeX/BibTeX children. A process that ignores the initial stop signal is forcibly stopped after one second. The project lock is then released. This cancellation does not use PID files to signal arbitrary processes.</p><p><strong>LaTeX — Open Build Log</strong> opens the current root&#39;s compiler log. Logs and cancellation state live in <code>~/.local/state/bbtex</code> by default, keyed by canonical root path; <code>BBTEX_STATE_DIR</code> overrides that location. CLI use also respects <code>XDG_STATE_HOME</code> when <code>BBTEX_STATE_DIR</code> is unset.</p><h2 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h2><p><strong>LaTeX — Clean</strong> removes auxiliary output with <code>latexmk -c</code>, preserving the PDF. <strong>LaTeX — Clean All Build Output</strong> uses <code>latexmk -C</code> to also remove the PDF; the BBEdit command asks before doing so. Both use the configured output directory and refuse to run during an active build. Cleanup requires latexmk, including for projects compiled with Tectonic.</p><h2 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profiles</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paths</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Draft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Draft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cancel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean-all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chapter.tex</span></span></code></pre></div><p>Compile exit codes: 0 success, 1 compilation errors, 2 setup/busy failure, 3 cancelled. The output protocol includes root, engine, duration, and build_log.</p><h2 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dune</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> runtest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/check_build_workflow.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/check_project_builds.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/check_project_saving.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test/integration/check_live_compile.py</span></span></code></pre></div><p>The cancellation check needs permission to signal its own compiler process group. The last two checks create disposable documents and require BBEdit/Skim scripting.</p><h2 id="experimental-ratex-placeholder" tabindex="-1">Experimental RaTeX placeholder <a class="header-anchor" href="#experimental-ratex-placeholder" aria-label="Permalink to &quot;Experimental RaTeX placeholder&quot;">​</a></h2><p><code>ratex</code> is accepted in the compiler picker, Configure Document, <code>.bbtex</code> engine settings, and <code>% !TEX program = ratex</code>. It refers to <a href="https://github.com/leoliu0/ratex" target="_blank" rel="noreferrer">leoliu0/ratex</a>, the full-document compiler. This is an optional experimental integration; bbtex does not install RaTeX or change the default engine. Its documented command is invoked directly with <code>-pdf -interaction=nonstopmode -output-directory=…</code>.</p><p>Actual RaTeX rendering, package compatibility, diagnostics and SyncTeX remain unverified. Keep using your established engine for normal work until RaTeX matures. The placeholder can also render snippets if a compatible <code>ratex</code> executable is installed; its snippet results are not cached.</p>`,33)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
